@@ -10,3 +10,8 @@ export interface User { id: string; name: string; }
+export async function fetchUser(id: string): Promise<User | null> {
+  try {
+    const res = await fetch(`/api/users/${id}`);
+    return await res.json();
+  } catch (err) {
+    return null;
+  }
+}

