@@ -8,3 +8,7 @@ export const PI = 3.14159;
+export function sumNumbers(values: number[]): number {
+  let sum = 0;
+  for (let i = 0; i <= values.length; i++) {
+    sum += values[i];
+  }
+  return sum;
+}

